import{_ as o,o as e,c as i,a2 as p}from"./chunks/framework.BXzK3EA4.js";const _=JSON.parse('{"title":"注意事项与最佳实践","description":"","frontmatter":{},"headers":[],"relativePath":"web/detail-page/dynamic-control/toggle-top-right-action-button-by-complex-logic/considerations.md","filePath":"web/detail-page/dynamic-control/toggle-top-right-action-button-by-complex-logic/considerations.md"}'),a={name:"web/detail-page/dynamic-control/toggle-top-right-action-button-by-complex-logic/considerations.md"};function n(l,t,r,s,c,g){return e(),i("div",null,[...t[0]||(t[0]=[p('<h1 id="注意事项与最佳实践" tabindex="-1">注意事项与最佳实践 <a class="header-anchor" href="#注意事项与最佳实践" aria-label="Permalink to &quot;注意事项与最佳实践&quot;">​</a></h1><ol><li><p><strong>逻辑执行时机需在页面渲染后</strong></p><p>按钮控制逻辑必须放在 afterRender 事件中执行，以确保组件已加载完成。若放在 beforeRender 或初始化阶段执行，可能导致组件实例尚未生成，从而无法正确获取或修改按钮属性。</p></li><li><p><strong>保持按钮初始状态明确</strong></p><p>在扩展配置中，应为按钮设置默认状态（如 visible: false），再在逻辑中按条件动态控制，避免页面闪烁或短暂显示错误状态。</p></li><li><p>统一管理按钮标识（buttonApiKey）</p><p>每个按钮都应有唯一标识。编写扩展逻辑时需确保 buttonApiKey 与页面配置一致，如 editCustomize、deleteCustomize。若命名不一致，逻辑将无法定位目标按钮。</p></li><li><p><strong>充分利用页面实例与数据获取方法</strong></p><p>通过 props.getInstance() 获取详情页实例，再使用 getDetailData() 获取当前记录数据。这是标准、稳定的数据访问方式，避免直接读取 props.data 或缓存变量，防止数据不同步。</p></li><li><p><strong>明确权限与业务条件的优先级</strong></p><p>若按钮控制逻辑同时依赖用户职能与业务字段，应优先判断权限（如角色或职能），再判断业务状态（如“草稿”）。明确优先级能减少逻辑冲突与误判。</p></li><li><p><strong>与系统权限模型保持同步</strong></p><p>当企业调整角色名称、职能编码或权限配置后，应同步更新扩展逻辑中的判断条件（如 DefaultAdmin）。否则可能导致权限不一致或越权操作。</p></li><li><p><strong>增加防空判断，确保逻辑稳健</strong></p><p>在逻辑判断中应校验字段值是否存在，例如：if (detailData?.amount__c &amp;&amp; detailData.amount__c &lt;= 5000000)，以避免空值或类型不匹配导致运行错误。</p></li><li><p><strong>避免逻辑过度复杂，保持注释清晰</strong></p><p>当存在多个按钮或多重条件时，应拆分逻辑块，使用清晰注释说明每一段逻辑的判断目标和范围，便于后续维护与排查。</p></li><li><p>保持多终端（网页端 / 移动端）逻辑一致</p><p>若两端均控制相同按钮，应确保逻辑一致、命名一致。可抽取公共逻辑或使用统一的判断方法，减少维护差异。</p></li><li><p><strong>调试时启用日志输出但生产环境禁用</strong></p><p>可通过 ctx.util.log() 或 ctx.util.error() 输出调试信息，便于排查逻辑执行情况。发布前应移除或注释日志，避免影响性能或暴露敏感信息。</p></li></ol>',2)])])}const m=o(a,[["render",n]]);export{_ as __pageData,m as default};
